// @name Calculator
// @background #000000
// @refresh 3600
// A calculator: five rows of keys share the height under the display, active:
// lights the key under the finger, and the operator waiting for its second
// number stays lit. = again repeats the last operation (2 + 3 = 5, = 8, = 11),
// as a pocket one does.
const rows = [
  ['C', '±', '%', '÷'],
  ['7', '8', '9', '×'],
  ['4', '5', '6', '−'],
  ['1', '2', '3', '+'],
]
const ops = {
  '+': (a, b) => a + b,
  '−': (a, b) => a - b,
  '×': (a, b) => a * b,
  '÷': (a, b) => a / b,
}

let display = '0'
let acc = null
let op = null
let fresh = true
let lastOp = null // what = repeats: the operator and its second number
let lastArg = null

// What a key changes on the screen: the display, the sum above it and which
// operator is lit. They are signals: a tap runs only the <Screen /> and the
// <OpKey />s that read them, not get().
const shown = signal('0')
const sumLine = signal('')
const lit = { '÷': signal(false), '×': signal(false), '−': signal(false), '+': signal(false) }
const showSum = () => {
  shown.value = display
  sumLine.value = op && acc !== null ? `${formatNumber(acc)} ${op}` : ''
  for (const key in lit) lit[key].value = key === op && fresh
}

// The sum in progress outlives the render: a board may start each render with
// a fresh module, and a frame rendered on its server does, at every tap.
let recalled = false
const recallSum = () => {
  if (recalled) return
  recalled = true
  const kept = frameos.recall('sum')
  if (kept) {
    display = kept.display
    acc = kept.acc
    op = kept.op
    fresh = kept.fresh
    lastOp = kept.lastOp
    lastArg = kept.lastArg
  }
  showSum()
}
const rememberSum = () => frameos.remember('sum', { display, acc, op, fresh, lastOp, lastArg })

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-black',
    sum: 'text-neutral-500',
    display: 'text-white',
    lit: 'bg-white text-orange-500',
    op: 'bg-orange-500 text-white active:bg-orange-300',
    fn: 'bg-neutral-400 text-black active:bg-neutral-200',
    digit: 'bg-neutral-800 text-white active:bg-neutral-600',
  },
  high: {
    page: 'bg-white',
    sum: 'text-black',
    display: 'text-black',
    lit: 'bg-white text-black border-4 border-black',
    op: 'bg-black text-white',
    fn: 'bg-white text-black border-2 border-black font-bold',
    digit: 'bg-white text-black border-2 border-black',
  },
}

// The keys take whatever height the screen has, so their labels and the
// display grow with them: a tall screen should not show pocket-sized digits.
// 156 px is the padding, the smallest display, its gap and the row gaps.
const sizes = (height) => {
  const keyHeight = (height - 156) / 5
  if (keyHeight >= 180) return { key: 'text-7xl', display: 'text-8xl', sum: 'text-3xl h-10', top: 'h-36' }
  if (keyHeight >= 120) return { key: 'text-5xl', display: 'text-7xl', sum: 'text-2xl h-8', top: 'h-28' }
  if (keyHeight >= 90) return { key: 'text-4xl', display: 'text-6xl', sum: 'text-xl h-7', top: 'h-24' }
  return { key: 'text-3xl', display: 'text-5xl', sum: 'text-lg h-6', top: 'h-20' }
}

const formatNumber = (n) => {
  if (!isFinite(n)) return 'Error'
  const s = String(parseFloat(n.toPrecision(9)))
  return s.length > 10 ? n.toExponential(3) : s
}

const press = (key) => {
  if (key >= '0' && key <= '9') {
    display = fresh || display === '0' ? key : display.length < 9 ? display + key : display
    fresh = false
  } else if (key === '.') {
    if (fresh) display = '0.'
    else if (!display.includes('.')) display += '.'
    fresh = false
  } else if (key === 'C') {
    display = '0'; acc = null; op = null; fresh = true; lastOp = null; lastArg = null
  } else if (key === '±') {
    if (display !== '0') display = display.startsWith('-') ? display.slice(1) : '-' + display
  } else if (key === '%') {
    display = formatNumber(parseFloat(display) / 100); fresh = true
  } else if (key === '=') {
    if (op && acc !== null) {
      lastOp = op; lastArg = parseFloat(display)
      display = formatNumber(ops[op](acc, lastArg))
    } else if (lastOp) {
      display = formatNumber(ops[lastOp](parseFloat(display), lastArg))
    }
    acc = null; op = null; fresh = true
  } else {
    if (op && acc !== null && !fresh) display = formatNumber(ops[op](acc, parseFloat(display)))
    acc = parseFloat(display); op = key; fresh = true
  }
  rememberSum()
  showSum()
}

const tone = (t, key) => {
  if (key in ops || key === '=') return t.op
  if (key === 'C' || key === '±' || key === '%') return t.fn
  return t.digit
}

const Key = ({ size, tone, k }) => (
  <div className={`flex-1 rounded-2xl flex items-center justify-center ${size} ${tone}`}
    onClick={() => press(k)}>{k}</div>
)

// An operator key, lit while it waits for its second number.
const OpKey = memo(({ size, t, k }) => <Key size={size} tone={lit[k].value ? t.lit : t.op} k={k} />)

const button = (t, s, key) =>
  key in lit ? <OpKey size={s.key} t={t} k={key} /> : <Key size={s.key} tone={tone(t, key)} k={key} />

const Screen = memo(({ top, sum, size, t }) => (
  <div className={`flex flex-col items-end justify-end px-3 ${top}`}>
    <span className={`${sum} ${t.sum}`}>{sumLine.value}</span>
    <span className={`${size} truncate ${t.display}`}>{shown.value}</span>
  </div>
))

// On a round panel the keys are round too, in five rows inside the circle,
// the display in the arc above them: every row as wide as its chord allows.
const RoundKey = ({ x, y, w, d, tone, k }) => (
  <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${d}px] rounded-full flex items-center justify-center text-2xl ${tone}`}
    onClick={() => press(k)}>{k}</div>
)
const RoundOpKey = memo(({ x, y, w, d, t, k }) => <RoundKey x={x} y={y} w={w} d={d} tone={lit[k].value ? t.lit : t.op} k={k} />)

const RoundScreen = memo(({ x, y, w, t }) => (
  <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] flex flex-col items-center`}>
    <span className={`text-lg h-6 ${t.sum}`}>{sumLine.value}</span>
    <span className={`text-5xl truncate ${t.display}`}>{shown.value}</span>
  </div>
))

const roundCalculator = (t, W, H) => {
  const cx = W / 2, cy = H / 2
  const R = Math.min(W, H) / 2 - 12
  const d = Math.round(R * 0.25)
  const gap = Math.round(d * 0.12)
  const bottom = Math.round(R * 0.75)
  const top = bottom - 5 * d - 4 * gap
  // One column spacing for every row, the widest the narrowest row allows.
  const far = Math.max(Math.abs(top), Math.abs(bottom))
  const chord = 2 * Math.sqrt(Math.max(0, R * R - far * far))
  const gx = Math.round(Math.max(gap, Math.min(d * 0.5, (chord - 4 * d) / 3)))
  const width = 4 * d + 3 * gx
  const keys = []
  const all = [...rows, ['0', '.', '=']]
  all.forEach((row, i) => {
    const y = top + i * (d + gap)
    let x = Math.round(cx - width / 2)
    for (const key of row) {
      const w = key === '0' ? 2 * d + gx : d
      keys.push(key in lit
        ? <RoundOpKey x={x} y={Math.round(cy + y)} w={w} d={d} t={t} k={key} />
        : <RoundKey x={x} y={Math.round(cy + y)} w={w} d={d} tone={tone(t, key)} k={key} />)
      x += w + gx
    }
  })
  // The display: 72 px above the keys, as wide as the circle is there.
  const screenTop = top - gap - 72
  const sw = Math.floor(2 * Math.sqrt(Math.max(0, R * R - (screenTop + 24) * (screenTop + 24))))
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <RoundScreen x={Math.round(cx - sw / 2)} y={Math.round(cy + screenTop)} w={sw} t={t} />
      {keys}
    </div>
  )
}

export function get(app, context) {
  recallSum()
  const t = highContrast(app) ? THEMES.high : THEMES.color
  if (context?.round === true) return roundCalculator(t, context.imageWidth, context.imageHeight)
  // The canvas's height, already turned with the frame (app.frame is the
  // panel's size before the turn).
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const H = context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)
  const s = sizes(H)
  // The last row is two halves with the rows' gap between them: a half is
  // exactly two keys and a gap, so 0 spans two columns and . and = line up.
  return (
    <div className={`flex flex-col gap-3 p-4 ${t.page}`}>
      <Screen top={s.top} sum={s.sum} size={s.display} t={t} />
      <div className="flex-1 flex flex-col gap-2">
        {rows.map((row) => (
          <div className="flex-1 flex gap-2">{row.map((key) => button(t, s, key))}</div>
        ))}
        <div className="flex-1 flex gap-2">
          <div className="flex-1 flex">{button(t, s, '0')}</div>
          <div className="flex-1 flex gap-2">{button(t, s, '.')}{button(t, s, '=')}</div>
        </div>
      </div>
    </div>
  )
}
